#!/bin/bash
cd "$(dirname "$0")"
{
cat <<'H'
<title>TURVIO Dispatch</title>
<meta name="claude:viewport-fit-sides" content="cover">
<link rel="icon" type="image/png" href="data:image/png;base64,">
<link rel="apple-touch-icon" href="data:image/png;base64,">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&display=swap">
<style>
H
cat ../brand/brand.css base.css mapstyle.css dispatch.css ../brand/sidebar-brand.css
cat <<'H'
</style>
<div class="app" id="app">
  <aside class="side" id="side"></aside>
  <div class="main">
    <header class="topbar" id="topbar"></header>
    <main class="page" id="page"></main>
  </div>
</div>
<div class="scrim" id="scrim"></div>
<div class="dlg" id="dlg" role="dialog" aria-modal="true"></div>
<div class="cmd" id="cmd" role="dialog" aria-modal="true" aria-label="Command"><input id="cmd-in" type="text" autocomplete="off"><div class="cmd-list" id="cmd-list"></div></div>
<div class="toasts" id="toasts" aria-live="polite"></div>
<script>
H
cat map.js data.js i18n.js app.js
echo '</script>'
} > index.html
(echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><style>[hidden]{display:none!important}body{margin:0}</style></head><body>'; cat index.html; echo '</body></html>') > preview.html
